for fpath in files_to_read:
    print(f"\n{'='*80}")
    print(f"FILE: {os.path.basename(fpath)}")
    print('='*80)
    try:
        doc = Document(fpath)
        for p in doc.paragraphs:
            print(p.text)
        for i, table in enumerate(doc.tables):
            print(f"\n--- TABLE {i+1} ---")
            for row in table.rows:
                cells = [cell.text for cell in row.cells]
                print(' | '.join(cells))
    except Exception as e:
        print(f"ERROR: {e}")
